        "sectionTitle": "PHẦN 2: THEO QUY ĐỊNH CỦA PHÁP LUẬT",
        "text": "Theo Nghị định 39/2016/NĐ-CP ngày 15/5/2016 của Chính phủ qui định: tai nạn lao động (TNLĐ) được phân loại như thế nào?",
