        "text": "Theo Luật ATVSLĐ số 84/2015/QH13 ngày 25/6/2015 của Quốc hội quy định: ai làm trưởng đoàn điều tra vụ tai nạn lao động (TNLĐ) làm bị thương 1 người?",
