        "sectionTitle": "PHẦN 2: THEO QUY ĐỊNH CỦA PHÁP LUẬT",
        "text": "Theo Luật ATVSLĐ số 84/2015/QH13 ngày 25/6/2015 của Quốc hội quy định: người lao động không có nghĩa vụ làm việc gì sau đây:",
