        "text": "Theo Luật ATVSLĐ số 84/2015/QH13 ngày 25/6/2015 của Quốc hội, nội dung nào sau đây không thuộc quyền hạn của bộ phận an toàn vệ sinh lao động tại cơ sở sản xuất?",
