        "sectionTitle": "PHẦN 2: THEO QUY ĐỊNH CỦA PHÁP LUẬT",
        "text": "Chuẩn bị nơi làm việc để đảm bảo an toàn khi tiến hành công việc thì phương pháp làm rào chắn như thế nào là đúng:",
