        "sectionTitle": "PHẦN 2: THEO QUY ĐỊNH CỦA PHÁP LUẬT",
        "text": "Khi ghi chỉ số công tơ điện thì phải thực hiện theo những biện pháp an toàn nào sau đây là đúng:",
