        "sectionTitle": "PHẦN 2: THEO QUY ĐỊNH CỦA PHÁP LUẬT",
        "text": "Theo Qui trình ATĐ ban hành theo Quyết định số 959/QĐ-EVN ngày 09/8/2018 qui định: Nếu xảy ra tai nạn, sự cố hoặc có thể gây mất an toàn cho người và hư hỏng thiết bị thì nhân viên vận hành phải xử lý thế nào?",
        "options": [
          {
            "label": "A",
            "text": "Nhân viên vận hành phải báo ngay cho nhân viên vận hành cấp trên và người quản lý trực tiếp của mình và xin cắt thiết bị ra khỏi hệ thống điện."
          },
          {
            "label": "B",
            "text": "Nhân viên vận hành phải báo ngay cho nhân viên vận hành cấp trên và xin cắt thiết bị ra khỏi hệ thống điện. Sau khi thao tác xong phải báo ngay cho người phụ trách trực tiếp của mình biết những nội dung công việc đã làm, đồng thời phải ghi đầy đủ vào sổ nhật ký vận hành."
          },
          {
            "label": "C",
            "text": "Nhân viên vận hành được phép cắt các máy cắt, dao cách ly mà không phải có lệnh hoặc phiếu thao tác, nhưng sau đó phải báo ngay cho nhân viên vận hành cấp trên và người phụ trách trực tiếp của mình biết những nội dung công việc đã làm, đồng thời phải ghi đầy đủ vào sổ nhật ký vận hành."
          },
          {
            "label": "D",
            "text": "Không có câu nào đúng."
          }
        ],
        "correctIndex": 0,
